const binaryData = $input.item.binary.file || $input.item.binary.data;

if (!binaryData) {
  throw new Error('No file data found in webhook');
}

const requestBody = {
  contents: [{
    parts: [
      {
        text: "You are a medical data extraction assistant. Analyze this medical report image and extract: hemoglobin (in g/dL), blood_sugar (in mg/dL), cholesterol (in mg/dL). Return ONLY valid JSON with keys: hemoglobin, blood_sugar, cholesterol, summary. Use 'N/A' if value not found."
      },
      {
        inline_data: {
          mime_type: binaryData.mimeType,
          data: binaryData.data
        }
      }
    ]
  }]
};

const response = await fetch(
  'https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=AIzaSyAx0gT_S2AnNrb_fpSYR6E3AMqmTcNe2-o',
  {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  }
);

const result = await response.json();

if (!response.ok) {
  throw new Error(`Gemini API error: ${JSON.stringify(result)}`);
}

return [{ json: result }];

const response = $input.item.json;
const text = response.candidates[0].content.parts[0].text;

let extracted = {
  hemoglobin: 'N/A',
  blood_sugar: 'N/A',
  cholesterol: 'N/A',
  summary: text
};

try {
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    extracted = {
      hemoglobin: parsed.hemoglobin || 'N/A',
      blood_sugar: parsed.blood_sugar || 'N/A',
      cholesterol: parsed.cholesterol || 'N/A',
      summary: parsed.summary || text
    };
  }
} catch (e) {
  console.log('Parse error:', e);
}

return [{ json: extracted }];
